import { spawnSync } from 'node:child_process';
import { cpSync, existsSync, mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const push = process.argv.includes('--push');
if (process.argv.slice(2).some(arg => arg !== '--push')) {
  throw new Error('Usage: node scripts/build-bundle.mjs [--push]');
}
function run(command, args, cwd = root, capture = false) {
  const result = spawnSync(command, args, {
    cwd, encoding: 'utf8', stdio: capture ? 'pipe' : 'inherit',
  });
  if (result.error) throw result.error;
  if (result.status !== 0) {
    throw new Error(`${command} ${args.join(' ')} failed (${result.status}): ${result.stderr || ''}`);
  }
  return result.stdout?.trim() || '';
}
const git = (args, cwd = root, capture = false) => run('git', args, cwd, capture);
function npm(args, cwd) {
  // npm.cmd must run through cmd.exe on Windows; arguments here are fixed.
  if (process.platform === 'win32') run(process.env.ComSpec || 'cmd.exe', ['/d', '/s', '/c', `npm ${args.join(' ')}`], cwd);
  else run('npm', args, cwd);
}
function clean(cwd) {
  if (git(['status', '--porcelain'], cwd, true)) throw new Error(`Uncommitted changes in ${cwd}`);
}
function commit(cwd, paths, message) {
  git(['add', '--', ...paths], cwd);
  const diff = git(['diff', '--cached', '--name-only'], cwd, true);
  if (!diff) return false;
  git(['commit', '-m', message,
    '-m', 'Co-authored-by: Copilot <223556219+Copilot@users.noreply.github.com>',
    '-m', 'Co-authored-by: OpenBot <335604065+openbotgit[bot]@users.noreply.github.com>'], cwd);
  return true;
}
if (git(['branch', '--show-current'], root, true) !== 'main') throw new Error('Run from main');
clean(root);
git(['submodule', 'update', '--init', '--recursive']);
for (const layer of ['backend', 'frontend', 'cli', 'bundle']) clean(join(root, layer));
git(['submodule', 'update', '--init', '--remote', 'backend', 'frontend', 'cli']);
const frontend = join(root, 'frontend');
npm(['ci', '--no-audit', '--no-fund'], frontend);
npm(['run', 'build'], frontend);
const publicDir = join(frontend, 'dist', 'snip-frontend', 'browser');
if (!existsSync(join(publicDir, 'index.html'))) throw new Error('Missing Angular browser/index.html');
const bundle = join(root, 'bundle');
const files = {
  'README.md': '# Generated Snip release\n\nGenerated by scripts/build-bundle.mjs on main. Do not hand-edit.\n',
  '.env': 'PUBLIC_DIR=./public\n',
  'package.json': JSON.stringify({ name: 'snip-bundle', private: true, scripts: { start: 'bun server.js' } }, null, 2) + '\n',
  'Dockerfile': 'FROM oven/bun:1-alpine\nWORKDIR /app\nCOPY . .\nENV PORT=3000\nENV PUBLIC_DIR=./public\nEXPOSE 3000\nCMD ["bun", "server.js"]\n',
  '.dockerignore': '.git\nnode_modules\n*.log\n.env\n',
  'railway.json': JSON.stringify({ build: { builder: 'DOCKERFILE', dockerfilePath: 'Dockerfile' }, deploy: { healthcheckPath: '/api/links', healthcheckTimeout: 30 } }, null, 2) + '\n',
  'release.json': JSON.stringify(Object.fromEntries(['backend', 'frontend', 'cli'].map(layer =>
    [layer, git(['rev-parse', 'HEAD'], join(root, layer), true)])), null, 2) + '\n',
};
rmSync(join(bundle, 'public'), { recursive: true, force: true });
mkdirSync(join(bundle, 'public'));
cpSync(publicDir, join(bundle, 'public'), { recursive: true });
for (const layer of ['backend', 'cli']) cpSync(join(root, layer, layer === 'backend' ? 'server.js' : 'cli.js'), join(bundle, layer === 'backend' ? 'server.js' : 'cli.js'));
for (const [name, content] of Object.entries(files)) writeFileSync(join(bundle, name), content);
const changed = commit(bundle, [...Object.keys(files), 'public', 'server.js', 'cli.js'], 'Generate Snip bundle');
const pointers = commit(root, ['backend', 'frontend', 'cli', 'bundle'], 'Pin Snip release commits');
if (push) {
  // Also publish local commits from a previous non-push run.
  git(['push', 'origin', 'HEAD:bundle'], bundle);
  git(['push', 'origin', 'HEAD:main']);
}
console.log(changed || pointers ? 'Bundle updated' : 'Bundle unchanged; nothing to commit');
